/* CreativeHub — Shared Design System */
/* Brand: #F02D00 (red-orange primary), #171717 (near-black), #FFFFFF */

:root {
  --brand: oklch(52% 0.24 29);          /* #F02D00 red-orange */
  --brand-dark: oklch(42% 0.22 29);
  --brand-light: oklch(62% 0.20 29);
  --fg: oklch(12% 0.01 265);            /* #171717 near-black */
  --fg-muted: oklch(45% 0.01 265);
  --fg-subtle: oklch(60% 0.01 265);
  --bg: #ffffff;
  --bg-surface: oklch(97% 0.005 265);
  --bg-card: #ffffff;
  --border: oklch(88% 0.01 265);
  --border-strong: oklch(78% 0.01 265);
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,.10), 0 2px 4px rgba(0,0,0,.06);
  --shadow-lg: 0 10px 30px rgba(0,0,0,.12), 0 4px 8px rgba(0,0,0,.06);
  --transition: 200ms ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', 'DM Sans', system-ui, -apple-system, sans-serif;
  color: var(--fg);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

/* ─── Typography ─── */
h1 { font-size: clamp(2rem, 4vw, 3rem); font-weight: 800; line-height: 1.15; letter-spacing: -0.02em; }
h2 { font-size: clamp(1.5rem, 3vw, 2.25rem); font-weight: 700; line-height: 1.2; letter-spacing: -0.01em; }
h3 { font-size: clamp(1.1rem, 2vw, 1.4rem); font-weight: 600; line-height: 1.3; }
h4 { font-size: 1.05rem; font-weight: 600; line-height: 1.35; }
p { line-height: 1.65; }
a { color: inherit; text-decoration: none; }

/* ─── Promo Banner ─── */
.promo-banner {
  background: var(--fg);
  color: #fff;
  text-align: center;
  padding: 10px 48px;
  font-size: 0.875rem;
  font-weight: 500;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}
.promo-banner .countdown { font-weight: 700; color: var(--brand); letter-spacing: 0.05em; }
.promo-banner .close-btn {
  position: absolute; right: 16px; background: none; border: none;
  color: #fff; font-size: 1.1rem; cursor: pointer; padding: 4px 8px;
  opacity: .7; transition: opacity var(--transition);
}
.promo-banner .close-btn:hover { opacity: 1; }

/* ─── Header / Nav ─── */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: #fff;
  border-bottom: 1px solid var(--border);
  padding: 0 clamp(16px, 4vw, 48px);
  height: 64px;
  display: flex; align-items: center; gap: 32px;
}
.site-logo {
  font-size: 1.3rem; font-weight: 900; color: var(--brand);
  letter-spacing: -0.03em; white-space: nowrap; flex-shrink: 0;
}
.site-logo span { color: var(--fg); }
.nav-links {
  display: flex; gap: 4px; align-items: center; flex: 1;
}
.nav-links a {
  padding: 6px 14px; border-radius: var(--radius-sm);
  font-size: 0.9rem; font-weight: 500;
  transition: background var(--transition), color var(--transition);
}
.nav-links a:hover, .nav-links a.active {
  background: var(--bg-surface); color: var(--brand);
}
.nav-search {
  flex: 1; max-width: 340px;
  display: flex; align-items: center; gap: 8px;
  background: var(--bg-surface); border: 1px solid var(--border);
  border-radius: 100px; padding: 8px 16px;
  font-size: 0.875rem; color: var(--fg-subtle);
  cursor: text;
}
.nav-search svg { flex-shrink: 0; }
.nav-actions { display: flex; gap: 8px; align-items: center; flex-shrink: 0; }
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  gap: 8px; padding: 9px 20px; border-radius: var(--radius-sm);
  font-size: 0.875rem; font-weight: 600; cursor: pointer;
  transition: all var(--transition); border: 1.5px solid transparent;
  text-decoration: none; line-height: 1;
}
.btn-outline {
  border-color: var(--fg); color: var(--fg); background: transparent;
}
.btn-outline:hover { background: var(--fg); color: #fff; }
.btn-primary {
  background: var(--brand); color: #fff; border-color: var(--brand);
}
.btn-primary:hover { background: var(--brand-dark); border-color: var(--brand-dark); }
.btn-secondary {
  background: var(--fg); color: #fff; border-color: var(--fg);
}
.btn-secondary:hover { background: oklch(20% 0.01 265); }
.btn-ghost {
  background: transparent; color: var(--fg-muted); border-color: transparent;
}
.btn-ghost:hover { background: var(--bg-surface); color: var(--fg); }
.btn-lg { padding: 14px 32px; font-size: 1rem; border-radius: var(--radius-md); }
.btn-sm { padding: 6px 14px; font-size: 0.8rem; }

/* ─── Course Card ─── */
.course-card {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border);
  transition: transform var(--transition), box-shadow var(--transition);
  cursor: pointer;
  display: flex; flex-direction: column;
}
.course-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}
.course-card-thumb {
  aspect-ratio: 16/9; background: var(--bg-surface);
  position: relative; overflow: hidden;
}
.course-card-thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }
.course-card-thumb .badge {
  position: absolute; top: 10px; left: 10px;
  background: var(--brand); color: #fff;
  font-size: 0.7rem; font-weight: 700;
  padding: 3px 8px; border-radius: 100px;
  text-transform: uppercase; letter-spacing: 0.04em;
}
.course-card-thumb .badge-gold {
  background: oklch(72% 0.18 80); color: var(--fg);
}
.course-card-body { padding: 14px 16px; flex: 1; display: flex; flex-direction: column; gap: 6px; }
.course-card-title { font-size: 0.9rem; font-weight: 600; line-height: 1.35; }
.course-card-instructor { font-size: 0.78rem; color: var(--fg-muted); }
.course-card-meta { display: flex; align-items: center; gap: 10px; font-size: 0.75rem; color: var(--fg-muted); margin-top: auto; }
.course-card-rating { color: oklch(72% 0.18 80); font-weight: 600; }
.course-card-price { display: flex; align-items: center; gap: 8px; margin-top: 4px; }
.course-card-price .current { font-size: 1rem; font-weight: 700; }
.course-card-price .original { font-size: 0.8rem; color: var(--fg-subtle); text-decoration: line-through; }
.course-card-price .disc { font-size: 0.75rem; color: var(--brand); font-weight: 600; }

/* ─── Section Layout ─── */
.section { padding: clamp(48px, 6vw, 96px) clamp(16px, 5vw, 80px); }
.section-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 32px; gap: 16px;
}
.section-title { font-size: clamp(1.25rem, 2.5vw, 1.75rem); font-weight: 700; }
.section-link { font-size: 0.875rem; font-weight: 600; color: var(--brand); white-space: nowrap; }
.section-link:hover { text-decoration: underline; }

/* ─── Carousel ─── */
.carousel-wrapper { position: relative; }
.carousel-track-outer { overflow: hidden; }
.carousel-track {
  display: flex; gap: 20px;
  transition: transform 400ms cubic-bezier(.4,0,.2,1);
}
.carousel-btn {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 44px; height: 44px; border-radius: 50%;
  background: #fff; border: 1.5px solid var(--border);
  box-shadow: var(--shadow-md);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; z-index: 10; color: var(--fg);
  transition: all var(--transition); flex-shrink: 0;
}
.carousel-btn:hover { background: var(--fg); color: #fff; border-color: var(--fg); }
.carousel-btn.prev { left: -22px; }
.carousel-btn.next { right: -22px; }
.carousel-btn:disabled { opacity: .35; pointer-events: none; }
.carousel-dots {
  display: flex; justify-content: center; gap: 8px; margin-top: 20px;
}
.carousel-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--border-strong); border: none; cursor: pointer;
  transition: all var(--transition); padding: 0;
}
.carousel-dot.active { background: var(--brand); width: 24px; border-radius: 100px; }

/* ─── Footer ─── */
.site-footer {
  background: var(--fg); color: #fff;
  padding: 64px clamp(16px, 5vw, 80px) 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 32px 24px;
  padding-bottom: 48px;
  border-bottom: 1px solid oklch(25% 0.01 265);
}
.footer-col h5 {
  font-size: 0.75rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.1em; color: oklch(60% 0.01 265); margin-bottom: 12px;
}
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 8px; }
.footer-col ul li a {
  font-size: 0.83rem; color: oklch(75% 0.01 265);
  transition: color var(--transition);
}
.footer-col ul li a:hover { color: #fff; }
.footer-bottom {
  display: flex; flex-wrap: wrap; align-items: center;
  justify-content: space-between; gap: 16px;
  padding-top: 32px;
}
.footer-legal { display: flex; flex-wrap: wrap; gap: 12px; font-size: 0.78rem; color: oklch(55% 0.01 265); }
.footer-legal a { color: inherit; }
.footer-legal a:hover { color: oklch(75% 0.01 265); }
.footer-brand { font-size: 1.1rem; font-weight: 900; color: var(--brand); }

/* ─── Footer accordion on mobile ─── */
@media (max-width: 768px) {
  .footer-col-toggle { cursor: pointer; display: flex; justify-content: space-between; align-items: center; }
  .footer-col-toggle h5 { margin-bottom: 0; }
  .footer-col ul { display: none; margin-top: 8px; }
  .footer-col.open ul { display: flex; }
  .footer-col-arrow { transition: transform var(--transition); }
  .footer-col.open .footer-col-arrow { transform: rotate(180deg); }
}

/* ─── Tags / Pills ─── */
.pill {
  display: inline-flex; align-items: center;
  padding: 4px 12px; border-radius: 100px;
  font-size: 0.78rem; font-weight: 600;
  border: 1.5px solid var(--border);
  color: var(--fg-muted); background: #fff;
  cursor: pointer; transition: all var(--transition); white-space: nowrap;
}
.pill:hover, .pill.active { background: var(--fg); color: #fff; border-color: var(--fg); }
.pill-brand { background: var(--brand); color: #fff; border-color: var(--brand); }
.pill-brand:hover { background: var(--brand-dark); border-color: var(--brand-dark); }

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .carousel-btn.prev { left: 0; }
  .carousel-btn.next { right: 0; }
}
@media (max-width: 768px) {
  .nav-search { display: none; }
  .nav-links { display: none; }
  .mobile-menu-btn { display: flex; }
  .site-header { gap: 16px; }
}

/* ─── Utility ─── */
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; }
.text-brand { color: var(--brand); }
.text-muted { color: var(--fg-muted); }
.text-subtle { color: var(--fg-subtle); }
.font-bold { font-weight: 700; }
.fw-800 { font-weight: 800; }
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.gap-8 { gap: 8px; }
.gap-16 { gap: 16px; }
.gap-24 { gap: 24px; }
.mt-8 { margin-top: 8px; }
.mt-16 { margin-top: 16px; }
.mt-24 { margin-top: 24px; }
.mt-32 { margin-top: 32px; }
.mb-8 { margin-bottom: 8px; }
.mb-16 { margin-bottom: 16px; }
.grid { display: grid; }
.hidden { display: none !important; }

/* ─── Thumb placeholders (color-coded by category) ─── */
.thumb-illustration { background: linear-gradient(135deg, oklch(70% 0.14 320) 0%, oklch(60% 0.18 300) 100%); }
.thumb-photo { background: linear-gradient(135deg, oklch(55% 0.12 220) 0%, oklch(45% 0.16 240) 100%); }
.thumb-design { background: linear-gradient(135deg, oklch(65% 0.18 160) 0%, oklch(52% 0.20 190) 100%); }
.thumb-motion { background: linear-gradient(135deg, oklch(60% 0.20 280) 0%, oklch(48% 0.18 250) 100%); }
.thumb-watercolor { background: linear-gradient(135deg, oklch(72% 0.14 40) 0%, oklch(68% 0.18 20) 100%); }
.thumb-sewing { background: linear-gradient(135deg, oklch(70% 0.12 80) 0%, oklch(62% 0.16 60) 100%); }
.thumb-social { background: linear-gradient(135deg, oklch(60% 0.16 200) 0%, oklch(52% 0.14 220) 100%); }
.thumb-sketch { background: linear-gradient(135deg, oklch(50% 0.04 265) 0%, oklch(35% 0.02 265) 100%); }
.thumb-ux { background: linear-gradient(135deg, oklch(62% 0.20 260) 0%, oklch(52% 0.22 280) 100%); }
.thumb-craft { background: linear-gradient(135deg, oklch(68% 0.14 100) 0%, oklch(58% 0.18 80) 100%); }

